($$santa-prisca$$, $$Santa Prisca$$, $$Virgem e Mártir$$, $$18 de Janeiro$$, 1, 18, NULL, NULL, '{}'::text[], $$Jovem romana martirizada por se recusar a sacrificar aos ídolos pagãos.$$, $$Jovem romana martirizada por se recusar a sacrificar aos ídolos pagãos.$$, $$[]$$::jsonb, '{}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg/440px-Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-mario-marta$$, $$Santos Mário e Marta$$, $$Mártires de Roma$$, $$19 de Janeiro$$, 1, 19, NULL, NULL, '{}'::text[], $$Família persa martirizada em Roma durante a perseguição de Cláudio.$$, $$Família persa martirizada em Roma durante a perseguição de Cláudio.$$, $$[]$$::jsonb, '{}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fra_Angelico_052.jpg/440px-Fra_Angelico_052.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-vicente$$, $$São Vicente Mártir$$, $$Diácono de Saragoça$$, $$22 de Janeiro$$, 1, 22, $$Séc. III, Huesca$$, $$304, Valência$$, '{"Lisboa","Viticultores","Diáconos"}'::text[], $$Diácono espanhol torturado cruelmente mas que manteve firmeza inabalável na fé durante a perseguição de Diocleciano.$$, $$Diácono espanhol torturado cruelmente mas que manteve firmeza inabalável na fé durante a perseguição de Diocleciano.$$, $$[]$$::jsonb, '{"\"O corpo está nas vossas mãos, mas a alma pertence a Deus.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fra_Angelico_052.jpg/440px-Fra_Angelico_052.jpg$$, NULL, '{"Fortaleza","Fidelidade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-ildefonso$$, $$Santo Ildefonso de Toledo$$, $$Defensor de Maria$$, $$23 de Janeiro$$, 1, 23, $$607, Toledo$$, $$667, Toledo$$, '{"Toledo"}'::text[], $$Arcebispo de Toledo, grande defensor da virgindade perpétua de Maria e autor de obras marianas célebres.$$, $$Arcebispo de Toledo, grande defensor da virgindade perpétua de Maria e autor de obras marianas célebres.$$, $$[]$$::jsonb, '{"\"Minha Senhora, meu domínio, Tu governas a mim e a tudo o que é meu.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/St-thomas-aquinas.jpg/440px-St-thomas-aquinas.jpg$$, NULL, '{"Devoção mariana"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-francisco-sales$$, $$São Francisco de Sales$$, $$Doutor do Amor$$, $$24 de Janeiro$$, 1, 24, $$1567, Saboia$$, $$1622, Lyon$$, '{"Jornalistas","Escritores","Surdos"}'::text[], $$Bispo de Genebra, mestre espiritual e padroeiro dos jornalistas. Autor da Introdução à Vida Devota.$$, $$Bispo de Genebra, mestre espiritual e padroeiro dos jornalistas. Autor da Introdução à Vida Devota.$$, $$[]$$::jsonb, '{"\"Uma gota de mel atrai mais moscas que um barril de vinagre.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/St-thomas-aquinas.jpg/440px-St-thomas-aquinas.jpg$$, NULL, '{"Mansidão","Caridade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
