($$sao-joao-britto$$, $$São João de Brito$$, $$O "Pandaru-Swami"$$, $$4 de Fevereiro$$, 2, 4, $$1647, Lisboa$$, $$1693, Oriyur, Índia$$, '{"Portugal","Índia"}'::text[], $$Jesuíta português missionário na Índia, martirizado por defender a fé cristã e adaptar-se aos costumes indianos para evangelizar.$$, $$Jesuíta português missionário na Índia, martirizado por defender a fé cristã e adaptar-se aos costumes indianos para evangelizar.$$, $$[]$$::jsonb, '{"\"O que recebi de Deus devo levar aos outros.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fra_Angelico_052.jpg/440px-Fra_Angelico_052.jpg$$, NULL, '{"Inculturação","Martírio"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-columbano-fev$$, $$São Columbano$$, $$Monge Missionário$$, $$7 de Fevereiro$$, 2, 7, NULL, NULL, '{}'::text[], $$Monge irlandês que fundou mosteiros por toda a Europa continental.$$, $$Monge irlandês que fundou mosteiros por toda a Europa continental.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$santa-josefina-bakhita$$, $$Santa Josefina Bakhita$$, $$A Flor do Sudão$$, $$8 de Fevereiro$$, 2, 8, $$1869, Darfur, Sudão$$, $$1947, Schio, Itália$$, '{"Vítimas de tráfico humano","Sudão"}'::text[], $$Sudanesa escravizada e torturada que encontrou a liberdade e a fé na Itália, tornando-se religiosa canossiana.$$, $$Sudanesa escravizada e torturada que encontrou a liberdade e a fé na Itália, tornando-se religiosa canossiana.$$, $$[]$$::jsonb, '{"\"Se eu encontrasse os que me escravizaram, ajoelharia e lhes beijaria as mãos, pois se isso não tivesse acontecido eu não seria agora cristã e religiosa.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg/440px-Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg$$, NULL, '{"Perdão","Fé","Humildade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$santa-apolonia$$, $$Santa Apolônia$$, $$Padroeira dos Dentistas$$, $$9 de Fevereiro$$, 2, 9, $$Séc. III, Alexandria$$, $$249, Alexandria$$, '{"Dentistas","Doenças de dentes"}'::text[], $$Mártir de Alexandria que teve todos os dentes arrancados antes de ser ameaçada de fogueira por sua fé.$$, $$Mártir de Alexandria que teve todos os dentes arrancados antes de ser ameaçada de fogueira por sua fé.$$, $$[]$$::jsonb, '{"\"Cristo é meu alimento e minha doçura.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fra_Angelico_052.jpg/440px-Fra_Angelico_052.jpg$$, NULL, '{"Fortaleza"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-bento-aniane$$, $$São Bento de Aniane$$, $$Reformador Beneditino$$, $$12 de Fevereiro$$, 2, 12, NULL, NULL, '{}'::text[], $$Monge que reformou a vida monástica no Império Carolíngio.$$, $$Monge que reformou a vida monástica no Império Carolíngio.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
