($$sao-corrado$$, $$São Conrado de Piacenza$$, $$Eremita Penitente$$, $$19 de Fevereiro$$, 2, 19, NULL, NULL, '{}'::text[], $$Nobre que causou um incêndio acidental e dedicou o resto da vida à penitência.$$, $$Nobre que causou um incêndio acidental e dedicou o resto da vida à penitência.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-eucherio$$, $$Santo Eucário de Orléans$$, $$Bispo$$, $$20 de Fevereiro$$, 2, 20, NULL, NULL, '{}'::text[], $$Bispo de Orléans que defendeu a Igreja contra as intromissões reais.$$, $$Bispo de Orléans que defendeu a Igreja contra as intromissões reais.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-pedro-damiao$$, $$São Pedro Damião$$, $$Reformador Monástico$$, $$21 de Fevereiro$$, 2, 21, $$1007, Ravena$$, $$1072, Faenza$$, '{"Caminhantes"}'::text[], $$Monge e cardeal reformador, autor de importantes obras teológicas e espirituais, defensor da disciplina eclesiástica.$$, $$Monge e cardeal reformador, autor de importantes obras teológicas e espirituais, defensor da disciplina eclesiástica.$$, $$[]$$::jsonb, '{"\"Não temas; se Deus te enviou esta provação, Ele te dará as forças para suportá-la.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/St-thomas-aquinas.jpg/440px-St-thomas-aquinas.jpg$$, NULL, '{"Zelo","Ascese"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-policarpo$$, $$São Policarpo de Esmirna$$, $$O Último dos Padres Apostólicos$$, $$23 de Fevereiro$$, 2, 23, $$69 d.C., Esmirna$$, $$155 d.C., Esmirna$$, '{"Enfermos"}'::text[], $$Bispo de Esmirna, discípulo do apóstolo São João, queimado vivo aos 86 anos por se recusar a amaldiçoar Cristo.$$, $$Bispo de Esmirna, discípulo do apóstolo São João, queimado vivo aos 86 anos por se recusar a amaldiçoar Cristo.$$, $$[]$$::jsonb, '{"\"Sirvo-O há 86 anos e Ele nunca me fez mal; como posso blasfemar contra meu Rei que me salvou?\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fra_Angelico_052.jpg/440px-Fra_Angelico_052.jpg$$, NULL, '{"Fidelidade","Martírio"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-modesto$$, $$São Modesto de Jerusalém$$, $$Patriarca$$, $$24 de Fevereiro$$, 2, 24, NULL, NULL, '{}'::text[], $$Patriarca de Jerusalém que restaurou os locais santos após a invasão persa.$$, $$Patriarca de Jerusalém que restaurou os locais santos após a invasão persa.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
