($$sao-porfirio$$, $$São Porfírio de Gaza$$, $$Destruidor de Ídolos$$, $$26 de Fevereiro$$, 2, 26, NULL, NULL, '{}'::text[], $$Bispo que eliminou os templos pagãos de Gaza com grande zelo missionário.$$, $$Bispo que eliminou os templos pagãos de Gaza com grande zelo missionário.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-gabriel-possenti$$, $$São Gabriel da Virgem Dolorosa$$, $$Jovem Santo$$, $$27 de Fevereiro$$, 2, 27, NULL, NULL, '{}'::text[], $$Jovem passionista italiano que alcançou grande santidade antes de morrer aos 24 anos.$$, $$Jovem passionista italiano que alcançou grande santidade antes de morrer aos 24 anos.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-romano$$, $$São Romano de Condat$$, $$Fundador de Mosteiros$$, $$28 de Fevereiro$$, 2, 28, NULL, NULL, '{}'::text[], $$Monge que fundou os mosteiros do Jura nos Alpes franceses.$$, $$Monge que fundou os mosteiros do Jura nos Alpes franceses.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$sao-david-gales$$, $$São David de Gales$$, $$Padroeiro do País de Gales$$, $$1 de Março$$, 3, 1, NULL, NULL, '{}'::text[], $$Monge e bispo galês do século VI, padroeiro do País de Gales.$$, $$Monge e bispo galês do século VI, padroeiro do País de Gales.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
