($$sao-joao-jose-cruz$$, $$São João José da Cruz$$, $$Franciscano$$, $$5 de Março$$, 3, 5, NULL, NULL, '{}'::text[], $$Frade franciscano napolitano famoso por seus milagres e vida de oração.$$, $$Frade franciscano napolitano famoso por seus milagres e vida de oração.$$, $$[]$$::jsonb, '{}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$santa-coleta$$, $$Santa Coleta$$, $$Reformadora Clarissa$$, $$6 de Março$$, 3, 6, NULL, NULL, '{}'::text[], $$Virgem que reformou a Ordem de Santa Clara, restaurando a pobreza original.$$, $$Virgem que reformou a Ordem de Santa Clara, restaurando a pobreza original.$$, $$[]$$::jsonb, '{}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg/440px-Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg$$, NULL, '{}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
